// a trait string "L9 K7 R9" -> { L: 9, K: 7, R: 9 } (a malformed token becomes "?token": -1, which the checker reports)
export function parseTraits(str) {
    const out = {};
    String(str).trim().split(/\s+/).filter(Boolean).forEach(tok => { const m = /^([A-Z])(\d)$/.exec(tok); if (m) out[m[1]] = Number(m[2]); else out["?" + tok] = -1; });
    return out;
}
